// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

contract MultiTenantMessageQueue {
    struct Message {
        bytes32 id;
        address sender;
        bytes payload;
        uint256 timestamp;
        bool consumed;
        uint256 tenantId;
    }

    struct Tenant {
        address admin;
        mapping(address => bool) authorizedConsumers;
        uint256 messageCount;
        bool active;
    }

    mapping(uint256 => Tenant) public tenants;
    mapping(bytes32 => Message) public messages;
    mapping(uint256 => bytes32[]) public tenantMessageIds;

    uint256 public tenantCounter;
    address public owner;

    event MessagePublished(bytes32 indexed msgId, uint256 indexed tenantId);
    event MessageConsumed(bytes32 indexed msgId, address indexed consumer);
    event ConsumerAuthorized(uint256 indexed tenantId, address indexed consumer);

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    modifier onlyTenantAdmin(uint256 _tenantId) {
        require(tenants[_tenantId].admin == msg.sender, "Not tenant admin");
        _;
    }

    constructor() {
        owner = msg.sender;
    }

    function createTenant(address _admin) external onlyOwner returns (uint256) {
        tenantCounter++;
        tenants[tenantCounter].admin = _admin;
        tenants[tenantCounter].active = true;
        return tenantCounter;
    }

    function authorizeConsumer(uint256 _tenantId, address _consumer) 
        external 
        onlyTenantAdmin(_tenantId) 
    {
        tenants[_tenantId].authorizedConsumers[_consumer] = true;
        emit ConsumerAuthorized(_tenantId, _consumer);
    }

    function revokeConsumer(uint256 _tenantId, address _consumer)
        external
        onlyTenantAdmin(_tenantId)
    {
        tenants[_tenantId].authorizedConsumers[_consumer] = false;
    }

    function publishMessage(uint256 _tenantId, bytes calldata _payload) external {
        require(tenants[_tenantId].active, "Tenant inactive");
        require(
            tenants[_tenantId].authorizedConsumers[msg.sender] || 
            tenants[_tenantId].admin == msg.sender,
            "Not authorized for tenant"
        );

        bytes32 msgId = keccak256(
            abi.encodePacked(_tenantId, msg.sender, block.timestamp, _payload)
        );

        messages[msgId] = Message({
            id: msgId,
            sender: msg.sender,
            payload: _payload,
            timestamp: block.timestamp,
            consumed: false,
            tenantId: _tenantId
        });

        tenantMessageIds[_tenantId].push(msgId);
        tenants[_tenantId].messageCount++;

        emit MessagePublished(msgId, _tenantId);
    }

    function _verifyConsumerAccess(
        address _consumer,
        uint256 _tenantId
    ) internal view returns (bool) {
        return tenants[_tenantId].authorizedConsumers[_consumer];
    }

    function consumeMessage(bytes32 _msgId) external returns (bytes memory) {
        Message storage msg_ = messages[_msgId];
        require(msg_.id != bytes32(0), "Message not found");
        require(!msg_.consumed, "Already consumed");

        // Verify consumer has access to the message's tenant
        uint256 msgTenantId = msg_.tenantId;
        require(
            _verifyConsumerAccess(msg.sender, msgTenantId) ||
            tenants[msgTenantId].admin == msg.sender,
            "Consumer not authorized"
        );

        msg_.consumed = true;
        emit MessageConsumed(_msgId, msg.sender);
        return msg_.payload;
    }

    function consumeBatch(bytes32[] calldata _msgIds) external returns (bytes[] memory) {
        bytes[] memory results = new bytes[](_msgIds.length);

        // Cache the first message's tenant for batch authorization
        require(_msgIds.length > 0, "Empty batch");
        Message storage firstMsg = messages[_msgIds[0]];
        require(firstMsg.id != bytes32(0), "First message not found");
        uint256 batchTenantId = firstMsg.tenantId;

        // Verify consumer access once for the batch
        require(
            _verifyConsumerAccess(msg.sender, batchTenantId) ||
            tenants[batchTenantId].admin == msg.sender,
            "Consumer not authorized for batch"
        );

        for (uint256 i = 0; i < _msgIds.length; i++) {
            Message storage currentMsg = messages[_msgIds[i]];
            require(currentMsg.id != bytes32(0), "Message not found");
            require(!currentMsg.consumed, "Already consumed");

            // Verify all messages belong to the same tenant context
            require(
                currentMsg.tenantId == batchTenantId,
                "Tenant mismatch in batch"
            );

            currentMsg.consumed = true;
            results[i] = currentMsg.payload;
            emit MessageConsumed(_msgIds[i], msg.sender);
        }

        return results;
    }

    function getMessagesByTenant(uint256 _tenantId) 
        external 
        view 
        returns (bytes32[] memory) 
    {
        require(
            tenants[_tenantId].authorizedConsumers[msg.sender] ||
            tenants[_tenantId].admin == msg.sender,
            "Not authorized"
        );
        return tenantMessageIds[_tenantId];
    }

    function isConsumerAuthorized(uint256 _tenantId, address _consumer)
        external
        view
        returns (bool)
    {
        return tenants[_tenantId].authorizedConsumers[_consumer];
    }
}
